// <noscript> content applies only when scripting is disabled, and <template>
// content is inert until it's cloned into the document. Both therefore form a
// scope of their own: <style>/<script> inside them must never be merged with
// the ones outside (in either direction), because that changes whether — and
// when — they apply.
const isolatedScopeTags = new Set([
    'noscript',
    'template'
]);
function isIsolatedScope(node) {
    return typeof node === 'object' && typeof node.tag === 'string' && isolatedScopeTags.has(node.tag);
}

function normalizeAttrsForKey(attrs, config) {
    const normalized = {
        ...config.baseAttrs
    };
    for (const [key, value] of Object.entries(attrs || {})){
        if (config.skippedAttrs.has(key) || value === undefined) {
            continue;
        }
        if (config.booleanAttrs.has(key)) {
            normalized[key] = true;
            continue;
        }
        normalized[key] = value;
    }
    return normalized;
}

exports.isIsolatedScope = isIsolatedScope;
exports.normalizeAttrsForKey = normalizeAttrsForKey;
